window.RP_SESSION={"id":"S-4db9e9aad4ed","messages":[{"id":"RP-II-0156887","time":"2026-08-20T02:31:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오즈발드 윌은…","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156888","time":"2026-08-20T02:31:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아니, 가델랏 허그는?","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156889","time":"2026-08-20T02:32:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아니 둘은??","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156890","time":"2026-08-20T02:32:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"지금 서부 사막의 어느곳에 있습니다.","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156891","time":"2026-08-20T02:32:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이 둘이 어쩌다가 만나게 됬을까요?","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156892","time":"2026-08-20T02:32:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156893","time":"2026-08-20T02:33:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"때는 전날 오후, 허그는 여느때와 같이 길드 로비에서 의뢰를 둘러보던 중이었습니다.","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156894","time":"2026-08-20T02:33:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“흐음… 어째 다들 시원시원하지가 않네? 호위 의뢰니, 죽치고 감시하는 의뢰니…”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156895","time":"2026-08-20T02:34:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“나도 내 일은 좀 하면서 지내고 싶은데 말이야. 뭐 괜찮은거 없으려나?”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156896","time":"2026-08-20T02:34:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 계속해서 의뢰지들을 두리번 두리번…","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156897","time":"2026-08-20T02:35:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그때, 저 멀리서 누군가 허그에게 말을 걸어옵니다.","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156898","time":"2026-08-20T02:36:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“안녕하십니까. 혹시 수주할 의뢰를 둘러보는 중이십니까?”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156899","time":"2026-08-20T02:37:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"배낭 밖으로 튀어나온 양피지들과 왼 손에 쥔 두꺼운 수첩.\n깔끔하게 넘긴 수염에 어쩐지 나긋나긋한 목소리의 이 사내는…","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156900","time":"2026-08-20T02:37:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오즈발드 윌!","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156901","time":"2026-08-20T02:37:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"둘은 이번이 첫 대면입니다.","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156902","time":"2026-08-20T02:39:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아, 여이. 그렇지 아무래도. 나도 계속 이곳에서 놀고 먹기만 하다보면 몸이 굳어버려서 말이야, 뭔가 괜찮은 일거리가 없을려나 한 번 봐봤는데 말이야…“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156903","time":"2026-08-20T02:39:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 영 괜찮은게 없구만~“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156904","time":"2026-08-20T02:39:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”아, 그러고 보니 처음 보는 얼굴인데. 혹시 이번에 새로 온 후배야?“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156905","time":"2026-08-20T02:40:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“네, 그렇습니다. 얼마전 어설픈 용맹 길드에 가입하게 된 오즈발드 윌이라고 합니다.”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156906","time":"2026-08-20T02:41:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”오즈발드라! 멋들어진 이름이네~ 혹시 그쪽은 무슨 일거리를 찾던 중이었대? 뭔가 순하게 생겨서 마수 때려잡고 그런 일은 안할 것 같은데 말이야.“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156907","time":"2026-08-20T02:44:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”아 그것 말씀이시군요. 저는 지도 제작자 겸 정령술사입니다.\n일 특성상 일리아의 여러 곳들을 둘러보고 다녀야 하기에 주로 동행 의뢰나 일손을 돕는 일거리들을 받곤 합니다만, 금전이  넉넉하지 않을때에는 사냥과 같이 조금은 위험한 일에도 가끔씩 거들어드리는 편입니다.“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156908","time":"2026-08-20T02:46:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 지도 제작자라고? 멋진걸! 그럼 등에 삐져나온 그 종이들도 지도 그릴려고 가지고 다니는 건가봐?\n일도 해야지 지도도 만들어야지… 바쁘겠는걸.”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156909","time":"2026-08-20T02:47:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“나는 가델랏 허그, 대형 몬스터 사냥꾼이라고. 지도 양반이랑은 다르게 그런 일들은 아직 익숙하지가 않아서 말이야, 가능한 사냥이라던가 싸우는 거라던가 그런 의뢰들을 찾아보고 있는데 말이지…”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156910","time":"2026-08-20T02:48:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄아아~ 영 안보이네.”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156911","time":"2026-08-20T02:48:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그때. 허그의 얘기를 듣던 오즈는…\n\n“아, 사냥 의뢰 말씀이신겁니까? 그렇다면 잠시… 아마 이쯤에 제가…“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156912","time":"2026-08-20T02:49:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"부스럭 부스럭, 자신의 겉옷 품 안쪽을 이리저리 뒤지더니만, 이내 깔끔하게 잘 접어진 의뢰지 하나를 허그에게 건넵니다.","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156913","time":"2026-08-20T02:49:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"의뢰지에 적힌 내용을 대충 읽어보자면…","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156914","time":"2026-08-20T02:50:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156915","time":"2026-08-20T02:50:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 지능 판정 :\n[6] + [1] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0156916","time":"2026-08-20T02:50:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…대형…몬스터? 오! 대형 몬스터라는군요!","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156917","time":"2026-08-20T02:50:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"근데 어떤 녀석인건지가 워낙 어렵게 적혀있는 바람에…","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156918","time":"2026-08-20T02:50:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”으으음… 뭔가 내쪽 일은 맞는 것 같은데 말이지… 도통 나머지는 뭐라고 적혀있는지를…“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156919","time":"2026-08-20T02:52:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”하하, 글을 읽는다는 것은 워낙에 어려운 일이니 말입니다. 저도 그리 볼 만한 실력은 아닙니다만, 아마 허그 님께서 놓치신 부분은 제가 읽어볼 수 있을 것 같습니다.“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156920","time":"2026-08-20T02:52:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“크흠, 그러면… 음…”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156921","time":"2026-08-20T02:52:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156922","time":"2026-08-20T02:52:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'오즈발드 윌'의 지능 판정 :\n[5] + [1] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0156923","time":"2026-08-20T02:52:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…음…”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156924","time":"2026-08-20T02:54:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“……크흠, 죄송하게도 어째서인지 이 부분은 저도 잘 모르겠습니다.\n그래도 다른 부분들을 읽어보자면, 사막 서쪽 오아시스 근방의… 음, 아마 이것은 의뢰의 장소로 보이는 듯 합니다. 아마 사막에서 서식하는 적을 상대해야 할 것 같군요.”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156925","time":"2026-08-20T02:54:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그리고 이것은…”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156926","time":"2026-08-20T02:55:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“클레이님, 아마 이것은 고…릴라? 라고 읽는 것 같습니다만, 저의 지식 상에서 사막에 고릴라라는 동물은 서식하지 않는 것으로 알고 있습니다. 그럼 이것은 대체…”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156927","time":"2026-08-20T02:59:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"[ 아니요, 오즈가 제대로 읽은 것이 맞을거에요. 평범한 동물 보다도 강한 힘을 가진 마수들은 원래 어울리지 않는 환경을 간혹 극복하고 이용하며 살아가기도 하니까요.\n그리고, 누가 알아요? 사막에 사는 고릴라들이 정말 있을지도. ]\n\n“허… 그렇다면…\n허그 님, 의뢰지의 정보를 읽어보았을 때 사막에 자리를 잡은 거대 고릴라 형 마수를 토벌하는 것이 이 의뢰에서 요구하는 바인 듯 합니다.“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156928","time":"2026-08-20T02:59:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”오~ 이번엔 또 그런 녀석인건가? 보면 볼수록 신기하단 말이야, 별의 별 녀석들을 다 마주친단 말이지~“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156929","time":"2026-08-20T03:00:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그럼, 지도 양반이 나한테 사냥 의뢰를 알려준건 아마 무슨 이유가 있을 것 같은데~ 같이 가달라는 걸려나?“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156930","time":"2026-08-20T03:02:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그렇습니다. 원래대로라면 다른 모험가 분들을 고용하여 동행하는 것도 방법 중 하나였으나, 마침 허그 님께서도 이와 같은 의뢰를 원하시는 듯 하기도 하며, 무엇보다 새로 얻은 인연과 겹치는 갈림길을 만난다면 그 쪽으로 걸어보는 것 또한 지도 제작자의 중요한 경험 중 하나이니 말입니다.“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156931","time":"2026-08-20T03:04:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그런 이유로, 가델랏 허그 님께 부탁드리는 바입니다. 이 의뢰를 함께 수행해주실 수 있으시겠습니까?\n거절을 원하신다면 말씀 부탁드립니다, 어디까지나 저의 책임으로 수주한 의뢰인 만큼 억지로 허그 님께 떠넘길 생각은 없으니 말입니다.”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156932","time":"2026-08-20T03:04:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“음… 그렇다면…“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156933","time":"2026-08-20T03:05:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…응! 여이, 나야말로 싫다고 할 이유가 없는걸? 마침 그쪽 같은 사람이 필요했었는데 말이야. 요술도 부리고, 뭔가 나보다 똑똑해 보이고 말이지.“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156934","time":"2026-08-20T03:06:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”좋아, 나는 찬성이라고! 원한다면야 기꺼이 같이 가줄테니 말이야~“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156935","time":"2026-08-20T03:06:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”아, 대신 잡은 녀석의 시체는 내가 처리하기다? 보수금은 그쪽이 대부분 가지고. 어때!“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156936","time":"2026-08-20T03:08:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”과연, 당신의 동행에 감사드립니다. 갑작스러운 부탁이었음에도 이렇게 흔쾌히 받아주시니, 저도 저의 나름대로 만반의 준비를 마친 뒤, 빠른 시일 내에 다시 뵙도록 하겠습니다.\n그럼 다시 한번 감사드리며, 그때 뵙도록 합시다.”","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156937","time":"2026-08-20T03:09:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 너무 긴장하진 말고~ 내가 잘 해볼테니깐 말이야, 식구들끼리 돕는거지 뭘!\n그럼 나도 내 철퇴나 잘 갈아둘테니까, 나중에 보자고.“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156938","time":"2026-08-20T03:09:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”네, 조심히 들어가십시오.“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156939","time":"2026-08-20T03:09:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이~!“","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156940","time":"2026-08-20T03:09:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"둘은 그렇게 인사를 나누며 헤어졌었고…","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156941","time":"2026-08-20T03:10:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이어서 지금, 둘은 의뢰의 장소에 막 도착했습니다!","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156942","time":"2026-08-20T03:11:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"과연 허그는 이번에야 말로, 허그와 처음 만난 후배는 무지하게 고생한다는 공식을 깨고 무사히, 멋들어진 선배로써 의뢰를 마칠 수 있을 건인가~","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156943","time":"2026-08-20T03:11:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"는 다음에 계속, 여이!","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156944","time":"2026-08-20T03:11:00+09:00","room":"RP II","name":"가델랏 허그 / 오즈발드 윌 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44","P-d40bea4fdee0"]},{"id":"RP-II-0156945","time":"2026-08-20T03:11:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
